    }
  }

  function setVolume(id, value) {
    ensureAudio();
    decks[id].volume.gain.setTargetAtTime(Math.max(0, Math.min(1, value)), audioContext.currentTime, 0.015);
    $(`#volume-label-${id}`).textContent = `${Math.round(value * 100)}%`;
  }

  function animate() {
