const autoMix = { active:false, step:0, steps:5, stopRequested:false };

function autoMixSetActive(active) {
  autoMix.active = active;
  $('#auto-mix-start').disabled = active;
  $('#auto-mix-next').disabled = !active;
  $('#auto-mix-stop').disabled = !active;
}

function setAutoMixStatus(title, description, progress) {
  $('#auto-mix-step-title').textContent = title;
  $('#auto-mix-description').textContent = description;
  $('#auto-mix-progress').textContent = progress;
}

async function runAutoMixStep(step) {
  ensureAudio();
  const a = decks.a, b = decks.b;
  switch(step) {
    case 1:
      if (!a.audio.src || !b.audio.src) { toast('Carga pistas en ambos decks o inicia las demos.'); stopAutoMix(); return; }
      setAutoMixStatus('PASO 1 · VERIFICAR', 'Ambos decks tienen audio. Preparando tempo.', 'Paso 1 / 5');
      break;
    case 2:
      setAutoMixStatus('PASO 2 · TEMPO', 'Igualando BPM de Deck B al de Deck A.', 'Paso 2 / 5');
      syncDeck('b'); // syncs B to A bpm and aligns time
      await delay(600);
      break;
    case 3:
      setAutoMixStatus('PASO 3 · FASE', 'Alineando el primer beat de Deck B.', 'Paso 3 / 5');
