} catch (error) {
  failed = true;
  checks.push({ name: 'Excepción', ok: false, detail: String(error) });
} finally {
  await browser.close();
}

for (const c of checks) {
  console.log(`${c.ok ? 'PASS' : 'FAIL'}: ${c.name}${c.detail ? ` — ${c.detail}` : ''}`);
}
if (failed) {
  console.error('SMOKE FAILED');
  process.exit(1);
} else {
  console.log('SMOKE OK');
  process.exit(0);
}
